<?php
declare(strict_types=1);
require __DIR__ . '/includes/bootstrap.php';
$user = app_require_permission('equipment.view');
$canAgent = app_has_permission('agent.equipment_skills', $user);
$csrf = app_csrf_token();
$assetId = preg_replace('/[^a-zA-Z0-9_-]/', '', (string)($_GET['id'] ?? '')) ?: '';
$return = (string)($_GET['return'] ?? 'equipment.php');
if (!preg_match('/^[a-zA-Z0-9_.?=&%\/-]+$/', $return)) $return = 'equipment.php';
?>
<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Equipment Asset Record</title>
<style>
:root{--bg:#f2f3f4;--panel:#fff;--line:#dce0e4;--ink:#17191c;--muted:#6d747d;--dark:#121416;--accent:#d94a2b;--good:#157347;--warn:#9a6200;--bad:#a62a24}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--ink)}button,input{font:inherit}.top{position:sticky;top:0;z-index:10;display:flex;align-items:center;gap:8px;padding:10px 14px;background:var(--dark);color:#fff}.top strong{margin-right:8px}.top button{border:1px solid #34383c;border-radius:8px;background:#1f2225;color:#fff;padding:8px 10px;cursor:pointer}.top .spacer{flex:1}.wrap{max-width:1250px;margin:auto;padding:20px}.hero{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;padding:20px;border:1px solid var(--line);border-radius:16px;background:#fff;margin-bottom:14px}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:var(--accent);font-weight:900}.hero h1{margin:5px 0 7px;font-size:32px}.muted{color:var(--muted);line-height:1.5}.pill{display:inline-flex;padding:5px 8px;border-radius:999px;background:#eef0f2;font-size:10px;font-weight:800}.pill.bad{background:#fff0ef;color:var(--bad)}.pill.warn{background:#fff6dd;color:var(--warn)}.grid{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:14px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:15px;margin-bottom:14px}.card h2{margin:0 0 10px;font-size:16px}.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.fact{padding:10px;border:1px solid #eceff1;border-radius:9px;background:#fafbfc}.fact small{display:block;color:var(--muted);text-transform:uppercase;font-size:8px;font-weight:800}.fact strong{display:block;margin-top:4px;font-size:12px;word-break:break-word}.text-block{padding:10px 0;border-bottom:1px solid #eceff1}.text-block:last-child{border-bottom:0}.text-block small{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;font-weight:850}.text-block p{margin:4px 0 0;font-size:12px;line-height:1.5;white-space:pre-wrap}.contact,.event{padding:9px 0;border-bottom:1px solid #eceff1;font-size:11px;line-height:1.45}.contact:last-child,.event:last-child{border-bottom:0}.agent{background:linear-gradient(145deg,#fff,#fff7f4);border-color:#efc7bb}.agent-row{display:flex;gap:6px}.agent-row input{flex:1;padding:8px;border:1px solid var(--line);border-radius:8px}.btn{border:1px solid var(--line);border-radius:8px;background:#fff;padding:8px 10px;cursor:pointer;font-weight:750}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.answer{margin-top:8px;padding:10px;border-radius:9px;background:#f5f5f3;white-space:pre-wrap;font-size:11px;line-height:1.5;max-height:300px;overflow:auto}.empty{padding:12px;border:1px dashed #c9ced4;border-radius:9px;color:var(--muted);text-align:center;font-size:11px}@media(max-width:900px){.grid{grid-template-columns:1fr}.facts{grid-template-columns:1fr 1fr}}
</style></head>
<body>
<header class="top"><strong>Equipment Asset Record</strong><button id="back">← Back</button><button onclick="location.href='equipment.php'">Full Equipment Catalog</button><div class="spacer"></div><button id="floorBtn" style="display:none">Show on Floor Plan</button></header>
<div class="wrap"><div id="content" class="empty">Loading equipment record…</div></div>
<script>
(()=>{'use strict';const ASSET_ID=<?= json_encode($assetId,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?>,RETURN=<?= json_encode($return,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?>,CAN_AGENT=<?= $canAgent?'true':'false' ?>,CSRF=<?= json_encode($csrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?>,$=id=>document.getElementById(id);let asset=null,events=[];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=v=>v===null||v===undefined||v===''?'—':esc(v);const money=v=>v===null||v===undefined||v===''?'—':'$'+Number(v).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
async function api(url,options={}){const o={...options,headers:{Accept:'application/json',...(options.headers||{})}};if(o.method&&o.method!=='GET')o.headers['X-CSRF-Token']=CSRF;if(o.body&&typeof o.body!=='string'){o.headers['Content-Type']='application/json';o.body=JSON.stringify(o.body)}const r=await fetch(url,o);const d=await r.json();if(!r.ok||d.ok===false)throw new Error(d.message||`Request failed (${r.status})`);return d}
function render(){if(!asset){$('content').className='empty';$('content').textContent='Equipment asset not found.';return}const age=asset.manufactureYear?Math.max(0,new Date().getFullYear()-asset.manufactureYear)+' years':'—',statusClass=asset.operationalStatus==='out_of_service'?'bad':asset.operationalStatus==='maintenance'?'warn':'';$('content').className='';$('content').innerHTML=`<section class="hero"><div><div class="eyebrow">Canonical restaurant equipment</div><h1>${esc(asset.name)}</h1><div class="muted">${esc(asset.purpose||'No purpose description recorded yet.')}</div></div><div><span class="pill ${statusClass}">${esc(asset.operationalStatus.replaceAll('_',' '))}</span></div></section><div class="grid"><main><section class="card"><h2>Identity & Lifecycle</h2><div class="facts">${[['Type',asset.assetType],['Brand',asset.brand],['Manufacturer',asset.manufacturer],['Model',asset.model],['Serial number',asset.serialNumber],['Asset tag',asset.assetTag],['Manufacture year',asset.manufactureYear],['Age',age],['Install date',asset.installDate],['Warranty expires',asset.warrantyExpiresOn],['Condition',asset.conditionStatus],['Criticality',asset.criticality]].map(([k,v])=>`<div class="fact"><small>${esc(k)}</small><strong>${fmt(v)}</strong></div>`).join('')}</div></section><section class="card"><h2>Physical, Utilities & Capacity</h2><div class="facts">${[['Location',asset.locationName],['Width',asset.widthInches?asset.widthInches+' in':''],['Depth',asset.depthInches?asset.depthInches+' in':''],['Height',asset.heightInches?asset.heightInches+' in':''],['Capacity',asset.capacityText],['Utility',asset.utilityType],['Voltage',asset.voltage],['Phase',asset.phase],['Amperage',asset.amperage],['BTU',asset.btuRating],['Water',asset.waterRequirement],['Drain',asset.drainRequirement],['Ventilation',asset.ventilationRequirement],['Purchase price',money(asset.purchasePrice)],['Replacement cost',money(asset.replacementCost)]].map(([k,v])=>`<div class="fact"><small>${esc(k)}</small><strong>${typeof v==='string'&&v.startsWith('$')?v:fmt(v)}</strong></div>`).join('')}</div></section><section class="card"><h2>Operating Knowledge</h2>${[['Cleaning instructions',asset.cleaningNotes],['Maintenance instructions',asset.maintenanceNotes],['Operating notes',asset.operatingNotes],['Safety notes',asset.safetyNotes],['Parts / consumables',asset.partsConsumables],['Other notes',asset.notes]].map(([k,v])=>`<div class="text-block"><small>${esc(k)}</small><p>${fmt(v)}</p></div>`).join('')}</section><section class="card"><h2>Service History</h2>${events.length?events.map(e=>`<div class="event"><strong>${esc(e.servicedOn)} · ${esc(e.eventType)}</strong><br>${esc(e.description)}${e.companyName?`<br><span class="muted">${esc(e.companyName)}${e.technicianName?' · '+esc(e.technicianName):''}</span>`:''}${e.cost!==null?`<br>Cost: ${money(e.cost)}`:''}${e.nextDueOn?`<br>Next due: ${esc(e.nextDueOn)}`:''}</div>`).join(''):'<div class="empty">No service events recorded.</div>'}</section></main><aside><section class="card"><h2>Maintenance</h2><div class="facts" style="grid-template-columns:1fr 1fr">${[['Scheduled',asset.maintenanceRequired?'Yes':'No'],['Interval',asset.maintenanceIntervalDays?asset.maintenanceIntervalDays+' days':''],['Last service',asset.lastServiceOn],['Next service',asset.nextServiceOn],['Expected life',asset.expectedLifeYears?asset.expectedLifeYears+' years':''],['Manual',asset.manualUrl?'Available':'']].map(([k,v])=>`<div class="fact"><small>${esc(k)}</small><strong>${fmt(v)}</strong></div>`).join('')}</div>${asset.manualUrl?`<p><a href="${esc(asset.manualUrl)}" target="_blank" rel="noopener">Open manufacturer/manual link ↗</a></p>`:''}</section><section class="card"><h2>Floor Plan</h2>${asset.floorPlanId?`<div class="text-block"><small>Plan</small><p>${esc(asset.floorPlanId)}</p></div><div class="text-block"><small>Component</small><p>${esc(asset.floorPlanComponentId||'Canonical asset placement')}</p></div>`:'<div class="empty">This asset is not placed on a floor plan.</div>'}</section><section class="card"><h2>Service Contacts</h2>${(asset.contacts||[]).length?asset.contacts.map(c=>`<div class="contact"><strong>${esc(c.companyName)}</strong>${c.contactName?` · ${esc(c.contactName)}`:''}<br>${esc(c.specialty||c.role||'Service')}${c.phone?`<br>${esc(c.phone)}`:''}${c.emergencyPhone?`<br><b>Emergency:</b> ${esc(c.emergencyPhone)}`:''}${c.email?`<br>${esc(c.email)}`:''}</div>`).join(''):'<div class="empty">No service contacts linked.</div>'}</section>${CAN_AGENT?`<section class="card agent"><h2>Equipment Brain</h2><div class="agent-row"><input id="question" placeholder="Ask about this asset..."><button class="btn primary" id="ask">Ask</button></div><div class="answer" id="answer">Ask about maintenance, repair contacts, model information, parts, operating notes, or this asset's floor-plan placement.</div></section>`:''}</aside></div>`;if(asset.floorPlanId){$('floorBtn').style.display='inline-block';$('floorBtn').onclick=()=>location.href='floor-planner-ops.php?plan='+encodeURIComponent(asset.floorPlanId)}if(CAN_AGENT){$('ask').onclick=ask;$('question').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();ask()}}}}
async function ask(){const q=$('question').value.trim();if(!q)return;$('answer').textContent='Thinking…';try{const d=await api('api/agent-brain.php',{method:'POST',body:{action:'ask',message:`Regarding ${asset.name}: ${q}`}});$('answer').textContent=d.answer||'No answer returned.'}catch(e){$('answer').textContent=e.message}}
async function load(){if(!ASSET_ID){$('content').textContent='No equipment asset id was provided.';return}try{const d=await api('api/equipment.php?asset='+encodeURIComponent(ASSET_ID),{method:'GET'});asset=(d.assets||[]).find(a=>a.id===ASSET_ID)||null;events=(d.events||[]).filter(e=>e.assetId===ASSET_ID);render()}catch(e){$('content').textContent=e.message}}
$('back').onclick=()=>location.href=RETURN;load();
})();
</script></body></html>